function style(n,o){
 if(o.dir){n.layoutMode=o.dir==='V'?'VERTICAL':'HORIZONTAL';n.layoutSizingHorizontal=o.w?'FIXED':'HUG';n.layoutSizingVertical=o.h?'FIXED':'HUG';
