  if(o.p!==undefined){let p=o.p;if(typeof p==='number')p=[p,p,p,p];if(p.length===2)p=[p[0],p[1],p[0],p[1]];['paddingTop','paddingRight','paddingBottom','paddingLeft'].forEach((f,i)=>{n[f]=p[i];if(SP.includes(p[i]))n.setBoundVariable(f,V['space/'+p[i]]);});}
 }
 if(o.w||o.h)n.resize(o.w||n.width,o.h||n.height);
 if('fill' in o)n.fills=typeof o.fill==='string'?[paint(o.fill)]:o.fill;
 if(o.stroke){n.strokes=[paint(o.stroke)];n.strokeWeight=o.sw||1;n.strokeAlign=o.sa||'INSIDE';}
